    "body": "音の間が広いほど、次へ急ぎたくなる。拍を埋めずに保つ練習をすると、ゆっくりした曲にも細かな動きが感じられた。\n\n準備から最初の試み、気づいた点を確かめる場面までを順に収録。最後に、次回変えてみたいことを短く話します。",
